function setTab(tab){activeTab=tab;document.querySelectorAll("[role=tab]").forEach(b=>b.setAttribute("aria-selected",String(b.dataset.tab===tab)));document.querySelectorAll(".tab-panel").forEach(p=>p.hidden=p.id!==`${tab}Panel`);if(tab==="operations")renderTrend(active());if(tab==="value")renderValue(active());if(tab==="diagnosis")renderDiagnosis(active())}
function changed(){rebuild();renderAll();setTab(activeTab)}
fetch("./data/demo/attribution_detail.json").then(r=>{if(!r.ok)throw Error("无法加载模拟数据");return r.json()}).then(data=>{rows=data;const ds=rows.map(r=>r.cohort_date).filter(Boolean).sort();$("dateStart").min=ds[0];$("dateStart").max=ds.at(-1);$("dateEnd").min=ds[0];$("dateEnd").max=ds.at(-1);fill("opsTrendMetric",trendOptions);fill("valueDimension",valueDims);fill("diagnosisMetric",Object.entries(diagMetrics).map(([v,d])=>[v,d.label]));fill("diagnosisDimension",diagDims);$("opsTrendMetric").value="openRate";$("valueDimension").value="service_provider";$("diagnosisMetric").value="opened";$("diagnosisDimension").value="service_provider";rebuild();filters.forEach(([id])=>$(id).addEventListener("change",changed));$("dateStart").addEventListener("change",changed);$("dateEnd").addEventListener("change",changed);$("opsTrendMetric").addEventListener("change",()=>renderTrend(active()));$("valueDimension").addEventListener("change",()=>renderValue(active()));$("diagnosisMetric").addEventListener("change",()=>renderDiagnosis(active()));$("diagnosisDimension").addEventListener("change",()=>renderDiagnosis(active()));$("diagnosisDrillGroup").addEventListener("change",()=>{const p=diagPeriods(active());renderDiagnosisDrill($("diagnosisMetric").value,$("diagnosisDimension").value,p.current)});$("reset").addEventListener("click",()=>{filters.forEach(([id])=>$(id).value="");$("dateStart").value="";$("dateEnd").value="";changed()});document.querySelectorAll("[role=tab]").forEach(b=>b.addEventListener("click",()=>setTab(b.dataset.tab)));renderAll();setTab("operations")}).catch(e=>document.querySelector("main").insertAdjacentHTML("afterbegin",`<p class="notice">看板加载失败：${e.message}。请通过本地 HTTP 服务或 GitHub Pages 打开页面。</p>`));
